"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command 'Add-Type -AssemblyName System.IO.Compression.FileSystem
$zipPath = '"'E:\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\dist\\codex-loop-open-source-20260820.zip'
"'$zip = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
$entries = $zip.Entries
$allNames = $entries | ForEach-Object { $_.FullName }

# Check for path traversal
$traversal = $allNames | Where-Object { $_ -match '"'\\.\\.' -or "'$_ -match '"'"'^/'"' -or "'$_ -match '"'"'^'"\\\\' -or "'$_ -match '"':[/\\\\]' }
Write-Host \"=== PATH TRAVERSAL (ZIP) ===\"
if ("'$traversal) { $traversal | ForEach-Object { Write-Host "  TRAVERSAL: $_" } } else { Write-Host "  CLEAN - none found" }

# Check for absolute paths
$absolute = $allNames | Where-Object { $_ -match '"'"'^[A-Za-z]:'"' -or "'$_ -match '"'"'^/'"' -or "'$_ -match '"'"'^'"\\\\\\\\' }
Write-Host \"=== ABSOLUTE PATHS (ZIP) ===\"
if ("'$absolute) { $absolute | ForEach-Object { Write-Host "  ABSOLUTE: $_" } } else { Write-Host "  CLEAN - none found" }

# Check for duplicates
$dupes = $allNames | Group-Object | Where-Object { $_.Count -gt 1 }
Write-Host "=== DUPLICATES (ZIP) ==="
if ($dupes) { $dupes | ForEach-Object { Write-Host "  DUPE ($($_.Count)x): $($_.Name)" } } else { Write-Host "  CLEAN - none found" }

# Check for case collisions (same name different case)
$lower = $allNames | ForEach-Object { $_.ToLower() }
$caseDupes = $lower | Group-Object | Where-Object { $_.Count -gt 1 }
Write-Host "=== CASE COLLISIONS (ZIP) ==="
if ($caseDupes) { $caseDupes | ForEach-Object { Write-Host "  CASE-DUPE ($($_.Count)x): $($_.Name)" } } else { Write-Host "  CLEAN - none found" }

$zip.Dispose()
'

