"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$srcRoot = '"'E:\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source'
"'$sha256file = Get-Content "$srcRoot'"\\SHA256SUMS\"

"'$mismatch = @()
$missing = @()
$extra = @()

foreach ($line in $sha256file) {
    if ([string]::IsNullOrWhiteSpace($line)) { continue }
    $parts = $line -split '"'  ', 2
    if ("'$parts.Count -ne 2) { continue }
    $expectedHash = $parts[0].Trim()
    $relPath = $parts[1].Trim() -replace '"'/', '\\'
    "'$fullPath = Join-Path $srcRoot $relPath

    if (-not (Test-Path $fullPath)) {
        $missing += $parts[1].Trim()
    } else {
        $actualHash = (Get-FileHash $fullPath -Algorithm SHA256).Hash.ToLower()
        if ($actualHash -ne $expectedHash) {
            $mismatch += "$($parts[1].Trim()): expected=$expectedHash actual=$actualHash"
        }
    }
}

# Check for files in the source tree not in SHA256SUMS
$allSrcFiles = Get-ChildItem $srcRoot -Recurse -File | Where-Object { $_.Name -ne '"'SHA256SUMS' } | ForEach-Object {
    "'$_.FullName.Substring($srcRoot.Length + 1) -replace '"'\\\\','/'
}
"'$listedFiles = $sha256file | ForEach-Object {
    if (-not [string]::IsNullOrWhiteSpace($_)) {
        ($_ -split '"'  ', 2)[1].Trim()
    }
} | Where-Object { "'$_ }

foreach ($f in $allSrcFiles) {
    if ($listedFiles -notcontains $f) {
        $extra += $f
    }
}

Write-Host "=== SHA256SUMS VERIFICATION (source tree) ==="
Write-Host "Files checked: $($sha256file.Count)"
if ($missing) { Write-Host "MISSING ($($missing.Count)):"; $missing | ForEach-Object { Write-Host "  MISSING: $_" } } else { Write-Host "  No missing files" }
if ($mismatch) { Write-Host "MISMATCH ($($mismatch.Count)):"; $mismatch | ForEach-Object { Write-Host "  MISMATCH: $_" } } else { Write-Host "  No hash mismatches" }
if ($extra) { Write-Host "EXTRA (not in SHA256SUMS) ($($extra.Count)):"; $extra | ForEach-Object { Write-Host "  EXTRA: $_" } } else { Write-Host "  No extra files" }
'

