"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '# Check duplicate content (same hash, different paths) in source tree
$srcRoot = '"'E:\\codex-LOOP\\deliveries\\codex-loop-github-open-source-20260820\\codex-loop-open-source'
"'$sha256file = Get-Content "$srcRoot'"\\SHA256SUMS\"

"'$hashMap = @{}
