    $hash = $parts[0].Trim()
    $path = $parts[1].Trim()

    if ($hashMap.ContainsKey($hash)) {
        $contentDupes += "Hash $hash shared by: $($hashMap[$hash]) AND $path"
    } else {
        $hashMap[$hash] = $path
    }
}

Write-Host "=== CONTENT DUPLICATES (same hash, different path) ==="
if ($contentDupes) {
    $contentDupes | ForEach-Object { Write-Host "  DUPE: $_" }
} else {
    Write-Host "  CLEAN - no content duplicates"
}
'

